#!/usr/bin/env python3
"""Build the static bilingual site using only Python's standard library."""
import json, html
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
E=html.escape
PRODUCTS=json.loads((ROOT/'data/portfolio.json').read_text())
CATS={'ai':('AI & connected work','AI & sammenhængende arbejde'),'creative':('Design & publishing','Design & publicering'),'education':('Education & learning','Uddannelse & læring'),'business':('Business & operations','Forretning & drift')}
def pick(v,lang): return v[1 if lang=='da' else 0] if isinstance(v,list) or isinstance(v,tuple) else v
COPY={
'nav':[['Ventures','Vores produkter'],['Our approach','Vores tilgang'],['Advisory','Rådgivning']],
'hello':['Let’s talk','Lad os tale sammen'], 'explore':['Explore our ventures','Se vores produkter'],
'eyebrow':['INDEPENDENT IDEAS. SHARED AMBITION.','SELVSTÆNDIGE IDÉER. FÆLLES AMBITION.'],
'hero':['Ideas become products.<br>Products become <span>businesses.</span>','Idéer bliver til produkter.<br>Produkter bliver til <span>virksomheder.</span>'],
'intro':['We’re Profectify. An independent venture studio building and running products that help people create, learn and get work done.','Vi er Profectify. Et uafhængigt venturestudio, der bygger og driver produkter, som hjælper mennesker med at skabe, lære og få arbejdet gjort.'],
'selected':['A few things<br>we’re building.','Noget af det,<br>vi bygger.'],
'selected_intro':['Different products. One hands-on approach. Meet some of the ventures we build, run and keep improving.','Forskellige produkter. Samme praktiske tilgang. Mød nogle af de produkter, vi bygger, driver og udvikler videre.'],
'all':['Meet the whole portfolio','Se hele porteføljen'],
'visit':['Visit website','Besøg hjemmesiden'],
'cta':['Good things start<br>with a conversation.','Gode ting begynder<br>med en samtale.'],
'cta_body':['A product question, a potential partnership, or a challenge worth working on. We’d like to hear it.','Et spørgsmål om et produkt, et muligt partnerskab eller en udfordring, der er værd at løse. Vi hører gerne fra dig.'],
'footer':['Independent ventures.<br>Built with purpose.','Selvstændige produkter.<br>Bygget med omtanke.'],
'skip':['Skip to content','Gå til indhold'],
'portfolio_title':['Many ideas.<br><span>Real products.</span>','Mange idéer.<br><span>Konkrete produkter.</span>'],
'portfolio_intro':['Find the right product for what you want to do. Explore our ventures across AI, design, education and business.','Find det rette produkt til det, du vil opnå. Gå på opdagelse i vores produkter inden for AI, design, uddannelse og forretning.'],
'about_title':['Curiosity starts it.<br><span>Building makes it real.</span>','Nysgerrighed starter det.<br><span>Vi bygger det til virkelighed.</span>'],
'about_intro':['Profectify is an independent, founder-led venture studio. We turn practical problems into products, then stay involved in the everyday work of running them.','Profectify er et uafhængigt, grundlæggerdrevet venturestudio. Vi omsætter konkrete problemer til produkter og bliver ved med at være en del af den daglige drift.'],
'adv_title':['Built on experience.<br><span>Shared through advisory.</span>','Bygget på erfaring.<br><span>Delt gennem rådgivning.</span>'],
'adv_intro':['Alongside our own ventures, we take on selected advisory engagements in people, operations and technology. Tell us what you’re working through.','Ved siden af vores egne produkter påtager vi os udvalgte rådgivningsopgaver inden for mennesker, drift og teknologi. Fortæl os, hvad I arbejder med.'],
'contact_title':['What’s on<br><span>your mind?</span>','Hvad har du<br><span>på hjerte?</span>'],
'contact_intro':['Let’s find the right conversation. For help with an existing product, contact that product’s support team directly.','Lad os finde den rette samtale. Har du brug for hjælp til et produkt, så kontakt produktets support direkte.'],
}
def t(key,lang):return pick(COPY[key],lang)
def link(page,lang):return ('/da/' if lang=='da' else '/')+page+'.html'
def mark():return '<span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span>'
def header(page,lang):
 other='en' if lang=='da' else 'da'
 nav=''.join(f'<a href="{link(p,lang)}"'+(' aria-current="page"' if p==page else '')+f'>{pick(label,lang)}</a>' for p,label in zip(['work','about','services'],COPY['nav']))
 return f'''<a class="skip" href="#main">{t('skip',lang)}</a><header class="site-header"><div class="wrap nav"><a class="brand" href="{link('index',lang)}" aria-label="Profectify">{mark()}Profectify<span class="brand-group">GROUP</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">{pick(['Menu','Menu'],lang)} <span>☰</span></button><nav id="navigation" aria-label="{pick(['Main navigation','Hovednavigation'],lang)}">{nav}<a class="language" href="{link(page,other)}" lang="{other}" hreflang="{other}" aria-label="{pick(['Skift til dansk','Switch to English'],lang)}">{'DA' if lang=='en' else 'EN'} ↗</a><a class="button small" href="{link('contact',lang)}">{t('hello',lang)} <span>↗</span></a></nav></div></header>'''
def footer(page,lang):
 return f'''<section class="closing"><div class="wrap closing-inner"><div><p class="eyebrow">{pick(['LET’S MAKE SOMETHING MATTER','LAD OS SKABE NOGET, DER BETYDER NOGET'],lang)}</p><h2>{t('cta',lang)}</h2><p>{t('cta_body',lang)}</p></div><a class="circle-link" href="{link('contact',lang)}" aria-label="{t('hello',lang)}">↗</a></div></section><footer class="site-footer wrap"><div><a class="brand" href="{link('index',lang)}">{mark()}Profectify</a><p>{t('footer',lang)}</p></div><div class="footer-links"><a href="{link('work',lang)}">{pick(['Our ventures','Vores produkter'],lang)}</a><a href="{link('about',lang)}">{pick(['Our approach','Vores tilgang'],lang)}</a><a href="{link('services',lang)}">{pick(['Advisory','Rådgivning'],lang)}</a><a href="mailto:hello@profectify.com">hello@profectify.com ↗</a></div><div class="footer-bottom"><span>© 2026 Profectify</span><span>{pick(['Built, run and always evolving.','Vi bygger, driver og udvikler videre.'],lang)}</span><a href="{link(page,'da' if lang=='en' else 'en')}">{'Dansk' if lang=='en' else 'English'} ↗</a></div></footer>'''
def wordmark(p):return f'<span class="product-symbol" aria-hidden="true">{p["symbol"]}</span><span>{E(p["name"])}</span>'
def art(p,lang):
 slug=p['slug']
 if slug=='heymadeit':return '<div class="product-art editor-art"><img src="/assets/img/heymadeit-editor.webp" alt="'+pick(['HeyMadeIt design editor with templates and a multi-page canvas','HeyMadeIts designeditor med skabeloner og et lærred med flere sider'],lang)+'" loading="lazy" width="800" height="450"></div>'
 if slug=='depaza':return '<div class="product-art chat-art"><div class="mini-sidebar"><b>◈ depaza</b><span>＋ '+pick(['New chat','Ny samtale'],lang)+'</span><span>↳ '+pick(['Projects','Projekter'],lang)+'</span></div><div class="chat-content"><span class="mini-kicker">EUROPEAN AI</span><strong>'+pick(['A little help.<br>A lot of possibility.','Lidt hjælp.<br>Mange muligheder.'],lang)+'</strong><div class="chat-input">'+pick(['What are we working on?','Hvad arbejder vi på?'],lang)+' <b>↑</b></div></div><span class="art-label">'+pick(['Product illustration','Produktillustration'],lang)+'</span></div>'
 if slug=='pipmcp':return '<div class="product-art pipes-art"><div class="app-chip">'+pick(['Your AI assistant','Din AI-assistent'],lang)+' <span>✳</span></div><div class="connector-line"></div><div class="pip-node">pip<span>MCP</span></div><div class="connector-branches"></div><div class="software-chips"><span>CRM</span><span>'+pick(['Accounting','Regnskab'],lang)+'</span><span>'+pick(['Webshop','Webshop'],lang)+'</span></div><span class="art-label">'+pick(['Connection illustration','Illustration af forbindelser'],lang)+'</span></div>'
 if slug=='heybrainey':return '<div class="product-art brain-art"><span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="brain-note note-one">'+pick(['Remember this.','Husk det her.'],lang)+'</span><img src="/assets/img/heybrainey.svg" alt="" width="72" height="98" loading="lazy"><span class="brain-note note-two">'+pick(['Right here when you need it.','Lige her, når du får brug for det.'],lang)+'</span></div>'
 if slug=='leadadapter':return '<div class="product-art leads-art"><span class="flow-step">01 <b>'+pick(['Start a conversation','Start en samtale'],lang)+'</b><i>↗</i></span><span class="flow-step">02 <b>'+pick(['Build a connection','Skab en forbindelse'],lang)+'</b><i>↗</i></span><span class="flow-step">03 <b>'+pick(['Keep it moving','Følg op'],lang)+'</b><i>↗</i></span></div>'
 return '<div class="product-art web-art"><div class="browser-bar"><i></i><i></i><i></i><span>heymadeweb</span></div><div class="web-preview"><span>'+pick(['YOUR NEXT CHAPTER','DIT NÆSTE KAPITEL'],lang)+'</span><strong>'+pick(['A home for<br>your business.','Et hjem til<br>din virksomhed.'],lang)+'</strong><div class="web-shapes"><i></i><i></i></div></div><span class="art-label">'+pick(['Website illustration','Hjemmesideillustration'],lang)+'</span></div>'
def card(p,lang,featured=False):
 if lang=='da' and p.get('name_da'): p={**p,'name':p['name_da']}
 desc=pick(p['description'],lang)
 return f'''<article class="venture-card {p['slug']}" data-category="{p['category']}" data-search="{E((p['name']+' '+desc).lower())}"><a href="{E(p['url'])}" target="_blank" rel="noopener noreferrer" aria-label="{E(p['name'])} — {t('visit',lang)} ({pick(['opens in a new tab','åbner i en ny fane'],lang)})">{art(p,lang) if featured else ''}<div class="card-info"><div class="card-meta"><span>{pick(CATS[p['category']],lang)}</span><span aria-hidden="true">↗</span></div><h3 class="product-wordmark">{wordmark(p)}</h3><p>{E(desc)}</p><span class="visit-label">{t('visit',lang)} ↗</span></div></a></article>'''
def approach(lang):
 rows=[(['01 / FIND THE FRICTION','01 / FIND UDFORDRINGEN'],['Start with a real problem.','Start med et konkret problem.'],['The best starting point is something that should be easier. We look for useful problems, close to the people doing the work.','Det bedste udgangspunkt er noget, der burde være lettere. Vi finder konkrete udfordringer tæt på de mennesker, der udfører arbejdet.']),(['02 / MAKE IT USEFUL','02 / GØR DET BRUGBART'],['Build it. Use it. Improve it.','Byg det. Brug det. Gør det bedre.'],['We bring product thinking, design and technology together. A useful first version gives us something real to learn from.','Vi samler produktudvikling, design og teknologi. En brugbar første version giver os noget konkret at lære af.']),(['03 / STAY INVOLVED','03 / BLIV VED'],['Running it is part of building it.','Driften er en del af udviklingen.'],['Launch is a beginning. Support, feedback and everyday operations shape what comes next.','Lanceringen er en begyndelse. Support, feedback og den daglige drift former det næste skridt.'])]
 return '<div class="approach-grid">'+''.join(f'<article><p class="eyebrow">{pick(a,lang)}</p><h3>{pick(b,lang)}</h3><p>{pick(c,lang)}</p></article>' for a,b,c in rows)+'</div>'
def home(lang):
 return f'''<section class="hero wrap"><div class="hero-heading"><p class="eyebrow"><span class="live-dot"></span>{t('eyebrow',lang)}</p><h1>{t('hero',lang)}</h1><div class="hero-bottom"><p>{t('intro',lang)}</p><a class="text-link" href="{link('work',lang)}">{t('explore',lang)} <span>↗</span></a></div></div><div class="hero-collage" aria-label="{pick(['A selection of Profectify products','Et udvalg af Profectifys produkter'],lang)}"><a class="collage-tile tile-design" href="https://heymadeit.com" target="_blank" rel="noopener"><span>✳ HeyMadeIt <b>↗</b></span><img src="/assets/img/heymadeit-editor.webp" width="800" height="450" alt="{pick(['HeyMadeIt design editor','HeyMadeIts designeditor'],lang)}"><small>{pick(['MAKE SOMETHING YOURS','SKAB NOGET, DER ER DIT'],lang)}</small></a><a class="collage-tile tile-ai" href="https://depaza.eu" target="_blank" rel="noopener"><span>◈ depaza <b>↗</b></span><strong>{pick(['Big ideas.<br>European AI.','Store idéer.<br>Europæisk AI.'],lang)}</strong><div class="spark" aria-hidden="true">✳</div></a><a class="collage-tile tile-connect" href="https://pipmcp.com" target="_blank" rel="noopener"><span>pipMCP <b>↗</b></span><div class="connected-icons" aria-hidden="true"><i>✳</i><em>↔</em><i>▦</i></div><small>{pick(['YOUR AI. YOUR SOFTWARE. CONNECTED.','DIN AI. DINE SYSTEMER. FORBUNDET.'],lang)}</small></a><a class="collage-tile tile-memory" href="https://heybrainey.com" target="_blank" rel="noopener"><span>HeyBrainey <b>↗</b></span><img src="/assets/img/heybrainey.svg" width="60" height="80" alt=""><strong>{pick(['Your memory.<br>Every AI.','Din hukommelse.<br>På tværs af AI.'],lang)}</strong></a><div class="collage-caption"><span class="tiny-cross">✳</span>{pick(['BUILT BY US. MADE FOR YOU.','BYGGET AF OS. SKABT TIL DIG.'],lang)}<span>↙</span></div></div></section><div class="brand-strip"><div class="wrap"><span>{pick(['PART OF THE SAME BIG PICTURE','EN DEL AF DET SAMME STØRRE BILLEDE'],lang)}</span><b>HeyMadeIt</b><b>depaza</b><b>pipMCP</b><b>LeadAdapter</b><b>HeyMadeWeb</b><b>SchoolBrowse</b></div></div><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">{pick(['THE VENTURES','PRODUKTERNE'],lang)}</p><h2>{t('selected',lang)}</h2></div><p>{t('selected_intro',lang)}</p></div><div class="featured-grid">{''.join(card(p,lang,True) for p in PRODUCTS if p.get('featured'))}</div><div class="section-end"><a class="button outline" href="{link('work',lang)}">{t('all',lang)} <span>↗</span></a></div></section><section class="approach-section"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">{pick(['HOW WE WORK','SÅDAN ARBEJDER VI'],lang)}</p><h2>{pick(['Hands on.<br>For the long run.','Hænderne i arbejdet.<br>Blikket fremad.'],lang)}</h2></div><a class="text-link" href="{link('about',lang)}">{pick(['Our approach','Vores tilgang'],lang)} ↗</a></div>{approach(lang)}</div></section><section class="advisory-teaser wrap"><span class="asterisk" aria-hidden="true">✳</span><div><p class="eyebrow">{pick(['EXPERIENCE, SHARED','ERFARING, DER DELES'],lang)}</p><h2>{pick(['Sometimes, we build alongside you.','Nogle gange bygger vi sammen med jer.'],lang)}</h2><p>{pick(['Selected advisory work in people, operations and technology. Grounded in the work of running our own ventures.','Udvalgt rådgivning om mennesker, drift og teknologi. Med afsæt i arbejdet med at drive vores egne produkter.'],lang)}</p></div><a class="text-link" href="{link('services',lang)}">{pick(['Explore advisory','Se vores rådgivning'],lang)} ↗</a></section>'''
def pagehero(title,intro,lang,kicker):return f'<section class="page-hero wrap"><p class="eyebrow">{kicker}</p><h1>{t(title,lang)}</h1><p class="page-intro">{t(intro,lang)}</p></section>'
def portfolio(lang):
 filters='<button type="button" aria-pressed="true" data-filter="all">'+pick(['All ventures','Alle produkter'],lang)+'</button>'+''.join(f'<button type="button" aria-pressed="false" data-filter="{k}">{pick(v,lang)}</button>' for k,v in CATS.items())
 return pagehero('portfolio_title','portfolio_intro',lang,pick(['OUR VENTURES','VORES PRODUKTER'],lang))+f'''<section class="wrap portfolio-section"><div class="portfolio-tools"><label class="search-label"><span>{pick(['Search our ventures','Søg i vores produkter'],lang)}</span><input type="search" id="venture-search" placeholder="{pick(['Try design, AI, schools…','Prøv design, AI, skoler…'],lang)}" autocomplete="off"></label><div class="filters" aria-label="{pick(['Filter by category','Filtrér efter kategori'],lang)}">{filters}</div></div><p class="result-count" aria-live="polite" data-result-count data-singular="{pick(['venture','produkt'],lang)}" data-plural="{pick(['ventures','produkter'],lang)}">{len(PRODUCTS)} {pick(['ventures','produkter'],lang)}</p><div class="directory-grid">{''.join(card(p,lang) for p in PRODUCTS)}</div><p class="no-results" hidden>{pick(['No matches. Try a different search or category.','Ingen resultater. Prøv en anden søgning eller kategori.'],lang)}</p></section>'''
def about(lang):
 return pagehero('about_title','about_intro',lang,pick(['OUR APPROACH','VORES TILGANG'],lang))+f'''<section class="story-panel wrap"><div class="story-graphic" aria-hidden="true"><span>✳</span><span>↗</span><span>◒</span><span>▦</span></div><div><p class="eyebrow">{pick(['A STUDIO THAT STAYS','ET STUDIO, DER BLIVER VED'],lang)}</p><h2>{pick(['From the first question<br>to the everyday details.','Fra det første spørgsmål<br>til hverdagens detaljer.'],lang)}</h2><p>{pick(['Our roots are in advisory: helping organisations work through people, operations and technology challenges. Building our own products brought those disciplines into one place.','Vores rødder er i rådgivning: at hjælpe organisationer med udfordringer inden for mennesker, drift og teknologi. Med vores egne produkter har vi samlet de discipliner ét sted.'],lang)}</p><p>{pick(['Today, our portfolio spans creative tools, connected AI, learning platforms and business software. Each venture has its own purpose. What connects them is practical curiosity and a commitment to keep making them more useful.','I dag spænder vores portefølje over kreative værktøjer, sammenhængende AI, læringsplatforme og forretningssoftware. Hvert produkt har sit eget formål. Fælles er praktisk nysgerrighed og arbejdet med at gøre produkterne mere brugbare.'],lang)}</p></div></section><section class="section wrap">{approach(lang)}</section><section class="connected-section wrap"><p class="eyebrow">{pick(['INDEPENDENT, TOGETHER','SELVSTÆNDIGE, SAMMEN'],lang)}</p><h2>{pick(['Different ambitions.<br>Shared experience.','Forskellige ambitioner.<br>Fælles erfaring.'],lang)}</h2><p>{pick(['Designing a print editor teaches us about creative workflows. Connecting software teaches us about permissions and useful automation. Building learning products keeps us focused on clarity. That experience travels across the group.','En designeditor lærer os om kreative arbejdsgange. Forbindelser mellem systemer lærer os om rettigheder og brugbar automatisering. Læringsprodukter holder os fokuseret på tydelighed. Den erfaring deler vi på tværs af gruppen.'],lang)}</p><a class="button" href="{link('work',lang)}">{t('explore',lang)} ↗</a></section>'''
def services(lang):
 rows=[(['People & organisation','Mennesker & organisation'],['Teams that can do their best work.','Teams med rammer til at lykkes.'],['People strategy, organisational design, leadership development and change. We help connect the way a business works with the people who make it work.','Personalestrategi, organisationsdesign, ledelsesudvikling og forandring. Vi hjælper med at forbinde virksomhedens arbejdsgange med de mennesker, der får dem til at fungere.']),(['Business & operations','Forretning & drift'],['Make the everyday work better.','Få hverdagen til at fungere bedre.'],['Clarify workflows, improve operating processes and work through growth challenges. Start with the friction, then build a practical way forward.','Skab tydelige arbejdsgange, forbedr driftsprocesser og håndtér vækstudfordringer. Vi tager udgangspunkt i udfordringen og finder en praktisk vej frem.']),(['Technology & leadership','Teknologi & ledelse'],['Connect the technology to the ambition.','Forbind teknologien med ambitionen.'],['Technical direction, product decisions, systems integration and fractional technical leadership. Hands-on support from discovery through delivery.','Teknisk retning, produktbeslutninger, systemintegration og teknisk ledelse på deltid. Praktisk støtte fra afklaring til levering.'])]
 return pagehero('adv_title','adv_intro',lang,pick(['SELECTED ADVISORY','UDVALGT RÅDGIVNING'],lang))+'<section class="wrap services-list">'+''.join(f'<article class="service-row"><span class="service-number">0{i+1}</span><div><p class="eyebrow">{pick(a,lang)}</p><h2>{pick(b,lang)}</h2><p>{pick(c,lang)}</p></div><span aria-hidden="true">↗</span></article>' for i,(a,b,c) in enumerate(rows))+f'</section><section class="wrap advisory-note"><h2>{pick(["A good fit starts with an honest conversation.","Et godt samarbejde starter med en ærlig samtale."],lang)}</h2><p>{pick(["Tell us about your situation, the decisions ahead and where you need support. We’ll discuss whether there’s a useful role for us.","Fortæl os om jeres situation, de beslutninger, I står overfor, og hvor I har brug for støtte. Så taler vi om, hvordan vi kan bidrage."],lang)}</p><a class="button" href="{link("contact",lang)}?topic=advisory">{t("hello",lang)} ↗</a></section>'
def contact(lang):
 topics=[('partnership',['Partnerships','Partnerskaber'],['Explore something together.','Lad os undersøge en mulighed sammen.']),('advisory',['Advisory','Rådgivning'],['Bring us a challenge.','Fortæl os om en udfordring.']),('general',['Something else','Noget andet'],['We’re listening.','Vi lytter.'])]
 return pagehero('contact_title','contact_intro',lang,pick(['SAY HELLO','SIG HEJ'],lang))+f'''<section class="wrap contact-grid"><div class="email-panel"><p class="eyebrow">{pick(['A DIRECT LINE','DIREKTE KONTAKT'],lang)}</p><h2>{pick(['Hello looks<br>good on you.','Det starter<br>med et hej.'],lang)}</h2><a href="mailto:hello@profectify.com">hello@profectify.com ↗</a><p>{pick(['Email us directly, or choose a topic to open an email draft in your email app.','Skriv direkte til os, eller vælg et emne for at åbne en kladde i dit mailprogram.'],lang)}</p></div><div class="contact-topics">{''.join(f'<a href="mailto:hello@profectify.com?subject={E(pick(a,lang))}"><div><h3>{pick(a,lang)}</h3><p>{pick(b,lang)}</p></div><span>↗</span></a>' for _,a,b in topics)}<p>{pick(['Need product support?','Brug for produktsupport?'],lang)} <a class="inline-link" href="{link('work',lang)}">{pick(['Find your product →','Find dit produkt →'],lang)}</a></p></div></section>'''
def notfound(lang):return f'<section class="page-hero wrap error-page"><p class="eyebrow">404</p><h1>{pick(["A little<br><span>off course.</span>","Lidt på<br><span>afveje.</span>"],lang)}</h1><p>{pick(["This page could not be found. Let’s get you back to the good stuff.","Vi kunne ikke finde siden. Lad os få dig tilbage på sporet."],lang)}</p><a class="button" href="{link("index",lang)}">{pick(["Back to the homepage","Til forsiden"],lang)} ↗</a></section>'
TITLES={'index':['Independent ventures. Built with purpose.','Selvstændige produkter. Bygget med omtanke.'],'work':['Our ventures','Vores produkter'],'about':['Our approach','Vores tilgang'],'services':['Advisory','Rådgivning'],'contact':['Contact','Kontakt'],'404':['Page not found','Siden blev ikke fundet']}
PAGES={'index':home,'work':portfolio,'about':about,'services':services,'contact':contact,'404':notfound}
for lang in ['en','da']:
 for page,render in PAGES.items():
  path=ROOT/('da' if lang=='da' else '')/(page+'.html'); path.parent.mkdir(exist_ok=True)
  canonical='https://profectify.com'+('/da/' if lang=='da' else '/')+('' if page=='index' else page+'.html')
  desc=t('intro',lang) if page=='index' else pick({'work':COPY['portfolio_intro'],'about':COPY['about_intro'],'services':COPY['adv_intro'],'contact':COPY['contact_intro'],'404':['Page not found.','Siden blev ikke fundet.']}[page],lang)
  alternate=''.join(f'<link rel="alternate" hreflang="{l}" href="https://profectify.com{link(page,l)}">' for l in ['en','da'])
  path.write_text(f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Profectify — {pick(TITLES[page],lang)}</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{canonical}">{alternate}<link rel="alternate" hreflang="x-default" href="https://profectify.com{link(page,'en')}"><meta property="og:type" content="website"><meta property="og:title" content="Profectify — {E(pick(TITLES[page],lang))}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://profectify.com/assets/img/social-card.png"><meta property="og:locale" content="{'da_DK' if lang=='da' else 'en_GB'}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/img/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/css/style.css"><script src="/assets/js/main.js" defer></script><noscript><style>@media(max-width:900px){{.nav{{height:auto;flex-wrap:wrap;padding-top:20px;padding-bottom:20px}}.nav nav{{display:flex;position:static;box-shadow:none;padding:10px 0;width:100%}}.menu-toggle{{display:none}}}}</style></noscript>{'<meta name="robots" content="noindex">' if page=='404' else ''}</head><body>{header(page,lang)}<main id="main">{render(lang)}</main>{footer(page,lang)}</body></html>'''.replace('><','>\n<'))
urls=['https://profectify.com'+('/da/' if l=='da' else '/')+('' if p=='index' else p+'.html') for l in ['en','da'] for p in PAGES if p!='404']
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in urls)+'</urlset>')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /data/\nDisallow: /scripts/\nDisallow: /output/\nSitemap: https://profectify.com/sitemap.xml\n')
print(f'Built {len(PAGES)*2} pages and sitemap from {len(PRODUCTS)} products.')
